//! Generator for the QMI service types of `rm-qmi`.
//!
//! The libqmi JSON service database is resolved into the message and TLV types
//! of every service, one Rust module per `qmi-service-*.json` file.

mod emit;
mod json;
mod model;
mod naming;

use std::error::Error;
use std::path::Path;

use proc_macro2::TokenStream;

use crate::services::{file_name, files, module_name};
use model::Database;

/// Header of the generated files.
const BANNER: &str = "//! Generated by `cargo xtask qmi-codegen`; do not edit.";

/// File name prefix of the service database.
const PREFIX: &str = "qmi-service-";

/// Generate `types.rs` and the `types/` modules of one crate.
pub fn generate(data: &Path, output: &Path) -> Result<(), Box<dyn Error>> {
    // A service may reference a common object defined by any other file, so
    // the database is loaded once for the whole tree.
    let database = Database::load(data);
    let files = files(data, PREFIX)?;
    let services = files
        .iter()
        .map(|file| database.service(file))
        .collect::<Vec<_>>();

    let mut manifest = String::from(BANNER);
    manifest.push_str(&format!(
        "\n//!\n//! Source: the libqmi service database in `{}`.\n\n",
        file_name(data)
    ));
    // Types expanded from the database are not written for the lints.
    manifest.push_str("#![allow(clippy::all)]\n\n");

    // Types the database repeats in every message are defined once, in the
    // `common` module the manifest lists first.
    manifest.push_str("pub mod common;\n\n");
    write_common(output, &shared_composites(&services)?)?;

    for (file, service) in files.iter().zip(&services) {
        let name = module_name(file, PREFIX);
        let header = format!("{BANNER}\n//!\n//! Source: `{}`.\n\n", file_name(file));
        let body = emit::module_body(service);
        let path = output.join("types").join(format!("{name}.rs"));

        crate::rust::write(&path, crate::rust::render(&header, &body))?;
        manifest.push_str(&format!("pub mod {name};\n"));
    }

    crate::rust::write(&output.join("types.rs"), manifest)
}

/// The composites every service repeats, in first seen order.
///
/// A name that turns out to have different members in different services is
/// rejected rather than silently shared.
fn shared_composites(services: &[model::Service]) -> Result<Vec<model::Composite>, Box<dyn Error>> {
    let mut shared: Vec<model::Composite> = Vec::new();
    let mut bodies: Vec<String> = Vec::new();

    for service in services {
        for composite in emit::shared_composites(service) {
            let body = emit::emit_composite(composite).to_string();

            match shared.iter().position(|seen| seen.name == composite.name) {
                Some(index) if bodies[index] != body => {
                    return Err(format!(
                        "`{}` is not the same type in every service",
                        composite.name
                    )
                    .into());
                }
                Some(_) => {}
                None => {
                    shared.push(composite.clone());
                    bodies.push(body);
                }
            }
        }
    }

    Ok(shared)
}

/// Write the module holding the shared composites.
fn write_common(output: &Path, shared: &[model::Composite]) -> Result<(), Box<dyn Error>> {
    let mut header = String::from(BANNER);
    header.push_str("\n//!\n//! Types the database repeats in almost every message.\n\n");
    header.push_str("#![allow(unused_imports)]\n\n");
    header.push_str("use crate::{Endian, Error, TlvBuf, TlvReader, TlvWriter};\n");
    header.push_str("use alloc::string::String;\n");
    header.push_str("use alloc::vec::Vec;\n\n");

    let body = shared
        .iter()
        .map(emit::emit_composite)
        .collect::<TokenStream>();

    crate::rust::write(
        &output.join("types").join("common.rs"),
        crate::rust::render(&header, &body),
    )
}
